with session_totals as (select session_id, sum(case when page = '/cart' then 1 else 0 end) as cart_count, min(duration_sec) as min_duration_sec from web_events where session_id in (10, 29) group by session_id) select s.id, s.browser, s.customer_id, st.cart_count, st.min_duration_sec from sessions s left outer join session_totals st on s.id = st.session_id where st.cart_count >= 65 order by st.min_duration_sec
